import XCTest
@testable import BandFaceKit

// Independently generated by Python zipfile with ZIP_DEFLATED. No executable app.
private let compressedFixture = ""

private func fixture() throws -> RpkFile { try RpkFile(data: Data(base64Encoded: compressedFixture)!) }

private func storedZIP(_ json: String, names: [String] = ["manifest.json"]) -> [UInt8] {
    let payload = Array(json.utf8), crc = Checksum.crc32(payload)
    var data: [UInt8] = [], directory: [UInt8] = []
    for name in names {
        let offset = UInt32(data.count), n = Array(name.utf8)
        data.appendLE32(0x04034b50);data.appendLE16(20);data.appendLE16(0);data.appendLE16(0)
        data.appendLE32(0);data.appendLE32(crc);data.appendLE32(UInt32(payload.count));data.appendLE32(UInt32(payload.count))
        data.appendLE16(UInt16(n.count));data.appendLE16(0);data += n + payload
        directory.appendLE32(0x02014b50);directory.appendLE16(20);directory.appendLE16(20)
        directory.appendLE16(0);directory.appendLE16(0);directory.appendLE32(0);directory.appendLE32(crc)
        directory.appendLE32(UInt32(payload.count));directory.appendLE32(UInt32(payload.count));directory.appendLE16(UInt16(n.count))
        directory.appendLE16(0);directory.appendLE16(0);directory.appendLE16(0);directory.appendLE16(0)
        directory.appendLE32(0);directory.appendLE32(offset);directory += n
    }
    let offset = UInt32(data.count);data += directory
    data.appendLE32(0x06054b50);data.appendLE16(0);data.appendLE16(0)
    data.appendLE16(UInt16(names.count));data.appendLE16(UInt16(names.count))
    data.appendLE32(UInt32(directory.count));data.appendLE32(offset);data.appendLE16(0)
    return data
}

final class RpkFileTests: XCTestCase {
    func testDeflatedManifestAndOriginalBytesPreserved() throws {
        let file = try fixture()
        XCTAssertEqual(file.id, "com.example.clock");XCTAssertEqual(file.name,"Clock")
        XCTAssertEqual(file.versionCode,7);XCTAssertEqual(file.versionName,"1.2")
        XCTAssertEqual(Data(file.data),Data(base64Encoded: compressedFixture))
    }
    func testStoredManifestAndDefaultVersion() throws {
        let file = try RpkFile(data: Data(storedZIP(#"{"package":"com.test.app","name":"Тест"}"#)))
        XCTAssertEqual(file.versionCode,1);XCTAssertEqual(file.name,"Тест")
    }
    func testRejectsTruncationCorruptionDuplicatesAndInvalidManifest() {
        let json = #"{"package":"com.test.app","name":"Test"}"#
        var corrupt = storedZIP(json);corrupt[45] ^= 1
        let cases = [Array(storedZIP(json).dropLast()),corrupt,storedZIP(json,names:["manifest.json","manifest.json"]),
                     storedZIP(json,names:["other.json"]),storedZIP(#"{"package":"../bad","name":"Test"}"#),
                     storedZIP(#"{"package":"app","name":"Test","versionCode":-1}"#)]
        for bytes in cases { XCTAssertThrowsError(try RpkFile(data:Data(bytes))) }
    }
    func testRpkCommandFieldNumbersAndWatchfaceEnvelopeUnchanged() throws {
        let start = try Command(body: Command.rpkInstallRequest(id:"pkg",versionCode:7,size:100))
        XCTAssertEqual(start.type,20);XCTAssertEqual(start.subtype,1)
        XCTAssertEqual(start.root.string(at:[22,2,1]),"pkg")
        XCTAssertEqual(start.root.varint(at:[22,2,2]),7);XCTAssertEqual(start.root.varint(at:[22,2,3]),100)
        let deletion = try Command(body:Command.rpkDeleteRequest(id:"pkg",sha:[0,255,19]))
        XCTAssertEqual(deletion.subtype,3);XCTAssertEqual(deletion.root.bytes(at:[22,5,2]),[0,255,19])
        let file = [UInt8](0...99), hash = BandCrypto.md5(file)
        let old = FileTransfer.stream(file:file,md5:hash)
        XCTAssertEqual(Array(old.prefix(2)),[0,16])
        let rpk = FileTransfer.stream(file:file,md5:hash,resumePosition:50,type:0x40)
        XCTAssertEqual(Array(rpk.prefix(2)),[0,64]);XCTAssertEqual(rpk.le32(at:18),100)
        XCTAssertEqual(Array(rpk[22..<(rpk.count-4)]),Array(file[50...]))
        XCTAssertEqual(rpk.le32(at:rpk.count-4),Checksum.crc32(Array(rpk.dropLast(4))))
    }
    func testMissingListIsNotTreatedAsEmpty() throws {
        XCTAssertThrowsError(try RpkInfo.list(from:Command(body:Command.rpkListRequest())))
    }
}

private actor RpkPeer: RpkCommandSession {
    let file: RpkFile
    var entries: [RpkInfo] = []
    var transferred: [[UInt8]] = []
    var deletes: [Command] = []
    var uploadType: UInt64?
    var addOnUpload = true
    var removeOnDelete = true
    var resume: UInt64 = 25
    var chunk: UInt64 = 64
    var startStatus: UInt64 = 0
    init(file:RpkFile) { self.file=file }
    func configure(existing:Bool=false,add:Bool=true,remove:Bool=true,resume:UInt64=25,chunk:UInt64=64,status:UInt64=0) {
        entries=existing ? [RpkInfo(id:file.id,name:file.name,sha:[9,8,7])] : []
        addOnUpload=add;removeOnDelete=remove;self.resume=resume;self.chunk=chunk;startStatus=status
    }
    func command(_ body:[UInt8], timeout:Duration?) async throws -> Command {
        let request=try Command(body:body)
        let response=Command.build(request.type,request.subtype) { w in
            if request.matches(20,0) {
                w.message(22) { r in r.message(1) { list in for app in entries { list.message(1) {
                    $0.string(1,app.id);$0.bytes(2,app.sha);$0.string(5,app.name)
                } } } }
            } else if request.matches(20,1) {
                w.message(22) { r in r.message(3) { $0.varint(1,startStatus) } }
            } else if request.matches(22,0) {
                uploadType=request.root.varint(at:[24,1,1])
                w.message(24) { r in r.message(2) { a in
                    a.bytes(1,file.md5);a.varint(2,0);a.varint(4,resume);a.varint(5,chunk)
                } }
            }
        }
        return try Command(body:response)
    }
    func sendCommandWithoutReply(_ body:[UInt8]) async throws {
        let command=try Command(body:body);deletes.append(command)
        if removeOnDelete { entries=[] }
    }
    func sendFileParts(_ parts:[[UInt8]],progress:(@Sendable(Int,Int)->Void)?) async throws {
        transferred=parts
        if addOnUpload { entries=[RpkInfo(id:file.id,name:file.name,sha:[9,8,7])] }
        progress?(parts.count,parts.count)
    }
}

final class RpkOperationTests: XCTestCase {
    func testInstallUsesRpkTypeResumeAndVerifiesNewListEntry() async throws {
        let file=try fixture(), peer=RpkPeer(file:file)
        let apps=try await RpkOperations(session:peer).install(file,progress:nil)
        XCTAssertEqual(apps.first?.id,file.id)
        let type=await peer.uploadType, parts=await peer.transferred
        XCTAssertEqual(type,64)
        let bytes=parts.flatMap { Array($0.dropFirst(4)) }
        XCTAssertEqual(bytes,FileTransfer.stream(file:file.data,md5:file.md5,resumePosition:25,type:0x40))
        XCTAssertEqual(parts.last?.le16(at:2),UInt16(parts.count))
    }
    func testAlreadyInstalledRejectsBeforeUploadAndDeletion() async throws {
        let file=try fixture(), peer=RpkPeer(file:file);await peer.configure(existing:true)
        do { _ = try await RpkOperations(session:peer).install(file,progress:nil);XCTFail("old ID reported as success") } catch {}
        let parts=await peer.transferred,deletes=await peer.deletes
        XCTAssertTrue(parts.isEmpty);XCTAssertTrue(deletes.isEmpty)
    }
    func testDeleteUsesCurrentOpaqueSHAAndNeedsNoCommandReply() async throws {
        let file=try fixture(), peer=RpkPeer(file:file);await peer.configure(existing:true)
        let stale=RpkInfo(id:file.id,name:"old",sha:[1])
        let result=try await RpkOperations(session:peer).delete(stale)
        XCTAssertTrue(result.isEmpty)
        let deletion=await peer.deletes.first
        XCTAssertEqual(deletion?.root.bytes(at:[22,5,2]),[9,8,7])
    }
    func testTransferAndDeleteWithoutListChangeAreNotSuccess() async throws {
        let file=try fixture(), peer=RpkPeer(file:file)
        var operations=RpkOperations(session:peer);operations.verificationAttempts=2;operations.verificationDelay = .milliseconds(1)
        await peer.configure(add:false)
        do { _ = try await operations.install(file,progress:nil);XCTFail("false install success") } catch {}
        await peer.configure(existing:true,remove:false)
        do { _ = try await operations.delete(RpkInfo(id:file.id,name:file.name,sha:[9]));XCTFail("false delete success") } catch {}
    }
    func testRejectedInstallAndInvalidUploadParametersStopBeforeData() async throws {
        let file=try fixture()
        for variant in 0..<3 {
            let peer=RpkPeer(file:file)
            await peer.configure(resume:variant==0 ? UInt64.max : 0,chunk:variant==1 ? 4 : 64,status:variant==2 ? 7 : 0)
            do { _ = try await RpkOperations(session:peer).install(file,progress:nil);XCTFail("accepted invalid parameters") } catch {}
            let data=await peer.transferred;XCTAssertTrue(data.isEmpty)
        }
    }
}
